What will be the output of the following C program?

c
#include <stdio.h>

void mystery(int n) {
    if (n <= 0)
        return;
    printf("%d ", n);
    mystery(n - 2);
    printf("%d ", n);
}

int main() {
    mystery(5);
    return 0;
}

